def count_row_column_matches(grid):
    rows = {tuple(r) for r in grid}
    cols = {tuple(c) for c in zip(*grid)}
    return len(rows & cols)

def count_row_column_matches(grid):
    rows = {}
    for row in grid:
        key = tuple(sorted(row))
        rows[key] = rows.get(key, 0) + 1
    return sum(rows.get(tuple(sorted(c)), 0) for c in zip(*grid))

def count_row_column_matches(grid):
    rows = {}
    for row in grid:
        key = "".join(map(str, row))
        rows[key] = rows.get(key, 0) + 1
    return sum(rows.get("".join(map(str, col)), 0) for col in zip(*grid))
